def calculate_m(A):
    N = len(A)
    m = 0
    for i in range(N):
        for j in range(i + 1, N):
            if A[j] == A[i] + 1:
                for k in range(j + 1, N):
                    if A[k] == A[j] + 1:
                        m += 1
    return m

A_example = [1, 2, 3, 2, 3, 4, 3, 4]
m_val = calculate_m(A_example)
print(f"For A={A_example}, m = {m_val}")

